from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==0 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=y+dy,x+dx
            if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
        comps.append((color,cells))
    def norm(cells):
      pts=[(y,x) for y,x in cells]; forms=[]
      for k in range(4):
        q=pts[:]
        for _ in range(k): q=[(x,-y) for y,x in q]
        my=min(y for y,x in q); mx=min(x for y,x in q)
        forms.append(frozenset((y-my,x-mx) for y,x in q))
      return min(forms,key=lambda q: sorted(q))
    templates={}
    for color,cells in comps:
      if color!=1: templates.setdefault(norm(cells),color)
    for color,cells in comps:
      if color==1 and norm(cells) in templates:
        for y,x in cells: out[y][x]=templates[norm(cells)]
    return out
